b0.push(A.dQ(a2,"Healthy","live, owned or legitimately rooted"))
b0.push(A.dQ(a2,"Orphan","owner freed, child still live past tau"))
b0.push(A.dQ(a2,"Hot","cluster growing past a threshold"))
b0.push(A.dQ(a2,"Freed","gone; removed in the next diff"))
